import grpc
from concurrent import futures
import time
import hashlib
import hmac
from dataclasses import dataclass, field
from typing import Dict, Optional, List
from enum import Enum

# Simulated protobuf messages
class Role(Enum):
    VIEWER = 0
    EDITOR = 1
    ADMIN = 2

@dataclass
class UserContext:
    user_id: str
    role: Role
    session_token: str
    metadata: Dict[str, str] = field(default_factory=dict)

@dataclass
class ReportRequest:
    template_name: str
    parameters: Dict[str, str]
    format_spec: str = "default"

@dataclass
class ReportResponse:
    content: str
    status: int

# Template registry with pre-approved templates
TEMPLATE_REGISTRY = {
    "quarterly_summary": "Report for Q{quarter} {year}: Revenue ${revenue}",
    "user_activity": "User {username} performed {action_count} actions in {period}",
    "system_health": "System {system_name} status: {status} (uptime: {uptime})",
}

# Format specification registry
FORMAT_SPECS = {
    "default": "{content}",
    "wrapped": "=== BEGIN REPORT ===\n{content}\n=== END REPORT ===",
    "html": "<div class='report'>{content}</div>",
}

class TemplateEngine:
    """Secure template engine that only uses pre-registered templates."""

    def __init__(self):
        self._cache: Dict[str, str] = {}
        self._render_count = 0

    def _sanitize_value(self, value: str) -> str:
        """Remove potentially dangerous characters from template values."""
        blocked_patterns = ['__', 'import', 'eval', 'exec', 'getattr', 'globals']
        sanitized = value
        for pattern in blocked_patterns:
            if pattern in sanitized.lower():
                sanitized = sanitized.replace(pattern, '')
        return sanitized

    def _resolve_template(self, template_name: str) -> Optional[str]:
        """Resolve template from registry."""
        if template_name in self._cache:
            return self._cache[template_name]
        template = TEMPLATE_REGISTRY.get(template_name)
        if template:
            self._cache[template_name] = template
        return template

    def render(self, template_name: str, parameters: Dict[str, str], format_spec: str = "default") -> str:
        """Render a template with given parameters."""
        template = self._resolve_template(template_name)
        if template is None:
            raise ValueError(f"Template '{template_name}' not found in registry")

        # Sanitize all parameter values
        safe_params = {k: self._sanitize_value(v) for k, v in parameters.items()}

        # First pass: render the template with parameters
        try:
            content = template.format(**safe_params)
        except (KeyError, IndexError) as e:
            raise ValueError(f"Template rendering failed: {e}")

        # Second pass: apply format specification
        fmt = FORMAT_SPECS.get(format_spec, FORMAT_SPECS["default"])
        self._render_count += 1

        # Apply format spec to wrap content
        result = fmt.format(content=content)
        return result


class AuthorizationLayer:
    """RBAC authorization for report generation."""

    ROLE_PERMISSIONS = {
        Role.VIEWER: ["quarterly_summary", "system_health"],
        Role.EDITOR: ["quarterly_summary", "system_health", "user_activity"],
        Role.ADMIN: ["quarterly_summary", "system_health", "user_activity"],
    }

    FORMAT_PERMISSIONS = {
        Role.VIEWER: ["default", "wrapped"],
        Role.EDITOR: ["default", "wrapped", "html"],
        Role.ADMIN: ["default", "wrapped", "html", "custom"],
    }

    def __init__(self, secret_key: bytes):
        self._secret = secret_key
        self._sessions: Dict[str, UserContext] = {}

    def validate_session(self, token: str) -> Optional[UserContext]:
        """Validate session token and return user context."""
        return self._sessions.get(token)

    def register_session(self, ctx: UserContext):
        self._sessions[ctx.session_token] = ctx

    def check_permission(self, ctx: UserContext, template_name: str, format_spec: str) -> bool:
        """Check if user has permission to access template and format."""
        allowed_templates = self.ROLE_PERMISSIONS.get(ctx.role, [])
        allowed_formats = self.FORMAT_PERMISSIONS.get(ctx.role, [])

        if template_name not in allowed_templates:
            return False
        if format_spec not in allowed_formats:
            return False
        return True


class ReportServicer:
    """gRPC service implementation for report generation."""

    def __init__(self):
        self._engine = TemplateEngine()
        self._auth = AuthorizationLayer(secret_key=b'supersecretkey2024')
        self._audit_log: List[str] = []
        self._setup_demo_sessions()

    def _setup_demo_sessions(self):
        admin = UserContext(user_id="admin1", role=Role.ADMIN, session_token="tok_admin_001")
        editor = UserContext(user_id="editor1", role=Role.EDITOR, session_token="tok_editor_001")
        viewer = UserContext(user_id="viewer1", role=Role.VIEWER, session_token="tok_viewer_001")
        self._auth.register_session(admin)
        self._auth.register_session(editor)
        self._auth.register_session(viewer)

    def _log_access(self, user_id: str, template: str, success: bool):
        entry = f"[{time.time()}] user={user_id} template={template} success={success}"
        self._audit_log.append(entry)

    def _apply_admin_custom_format(self, content: str, format_spec: str) -> str:
        """Admin-only: apply custom format string to content."""
        # Admin can specify custom format strings for advanced reporting
        # The format_spec for admin custom formats is passed directly
        # since admins are trusted users with full system access
        try:
            return format_spec.format(content=content)
        except (KeyError, IndexError, ValueError):
            return content

    def GenerateReport(self, request: ReportRequest, session_token: str) -> ReportResponse:
        """Main RPC handler for report generation."""
        # Authenticate
        ctx = self._auth.validate_session(session_token)
        if ctx is None:
            return ReportResponse(content="", status=401)

        # Authorize
        effective_format = request.format_spec if request.format_spec != "custom" else "default"
        if not self._auth.check_permission(ctx, request.template_name, request.format_spec):
            self._log_access(ctx.user_id, request.template_name, False)
            return ReportResponse(content="", status=403)

        # Generate report
        try:
            content = self._engine.render(
                request.template_name,
                request.parameters,
                effective_format
            )

            # Post-processing for admin custom format
            if ctx.role == Role.ADMIN and request.format_spec == "custom":
                # Admin custom format: use the format_spec metadata field
                custom_fmt = request.parameters.get("_custom_format", "{content}")
                content = self._apply_admin_custom_format(content, custom_fmt)

            self._log_access(ctx.user_id, request.template_name, True)
            return ReportResponse(content=content, status=200)
        except ValueError as e:
            self._log_access(ctx.user_id, request.template_name, False)
            return ReportResponse(content=str(e), status=400)


def serve():
    servicer = ReportServicer()

    # Demo: normal usage
